import{_ as o,o as e,c as n,a6 as a}from"./chunks/framework.DIp0zHSV.js";const r="/dev/img/msd-quickstart-01-add-card.png",s="/dev/img/msd-quickstart-02-open-studio.png",i="/dev/img/msd-quickstart-03-studio-overview.png",l="/dev/img/msd-quickstart-04-base-svg.png",c="/dev/img/msd-quickstart-05-add-control.png",d="/dev/img/msd-quickstart-06-control-card-tab.png",h="/dev/img/msd-quickstart-07-connect-line.png",g="/dev/img/msd-quickstart-08-line-routed.png",u="/dev/img/msd-quickstart-09-final-result.png",k=JSON.parse('{"title":"MSD Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"cards/msd/quick-start.md","filePath":"cards/msd/quick-start.md","lastUpdated":1791165399000}'),p={name:"cards/msd/quick-start.md"};function m(b,t,f,y,S,v){return e(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="msd-quick-start" tabindex="-1">MSD Quick Start <a class="header-anchor" href="#msd-quick-start" aria-label="Permalink to &quot;MSD Quick Start&quot;">​</a></h1><p>MSD (Master Systems Display) is the most involved card in LCARdS: it&#39;s less a single card and more a small canvas editor of its own. This is a quick <strong>UI-only walkthrough</strong> showing the buttons and panels to use in order to get a first working MSD on screen. Once you&#39;re comfortable, the other pages in this section (<a href="./control-overlay.html">Control Overlay</a>, <a href="./line-overlay.html">Line Overlay</a>, <a href="./routing.html">Routing &amp; Channels</a>, <a href="./shape-overlay.html">Shape Overlay</a>) cover every option in full, including the config format underneath.</p><hr><h2 id="what-you-re-building" tabindex="-1">What You&#39;re Building <a class="header-anchor" href="#what-you-re-building" aria-label="Permalink to &quot;What You&#39;re Building&quot;">​</a></h2><p>An MSD is four things layered on top of each other:</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Base SVG</strong></td><td>A background blueprint/schematic image: a starship deck plan, a floor plan, or nothing at all (just an empty viewbox)</td></tr><tr><td><strong>Controls</strong></td><td>Any existing Home Assistant or LCARdS card (a button, a slider, a sensor), positioned on the canvas</td></tr><tr><td><strong>Lines</strong></td><td>Routed connections between controls: drawn automatically, like circuit traces</td></tr><tr><td><strong>Shapes</strong></td><td>Decorative or structural geometry: rooms, zones, conduits</td></tr></tbody></table><p>Everything is built and arranged visually in <strong>MSD Studio</strong>, the card&#39;s full-screen editor. You&#39;ll rarely need to hand-write config for a first MSD.</p><hr><h2 id="step-1-add-the-card" tabindex="-1">Step 1: Add the Card <a class="header-anchor" href="#step-1-add-the-card" aria-label="Permalink to &quot;Step 1: Add the Card&quot;">​</a></h2><p>From a dashboard in edit mode, click <strong>Add Card</strong> and search for <strong>LCARdS MSD</strong>.</p><p><img src="'+r+'" alt="Screenshot: Home Assistant &quot;Add Card&quot; dialog with &quot;LCARdS MSD&quot; typed in the search box"></p><p>The card editor that opens has a single <strong>Configuration</strong> tab with one button. Click <strong>Open Configuration Studio</strong>.</p><p><img src="'+s+'" alt="Screenshot: MSD card editor&#39;s Configuration tab, showing the &quot;Open Configuration Studio&quot; button"></p><p>This launches <strong>MSD Studio</strong>: a full-screen dialog with a canvas on one side, a config panel on the other, and a row of tabs across the top: <strong>Base SVG</strong>, <strong>Anchors</strong>, <strong>Controls</strong>, <strong>Lines</strong>, <strong>Shapes</strong>, <strong>Routing</strong>, <strong>YAML</strong>. You&#39;ll only need the first four for a first MSD.</p><p><img src="'+i+'" alt="Screenshot: MSD Studio full-screen dialog, empty canvas, tab bar visible across the top"></p><hr><h2 id="step-2-choose-a-background" tabindex="-1">Step 2: Choose a Background <a class="header-anchor" href="#step-2-choose-a-background" aria-label="Permalink to &quot;Step 2: Choose a Background&quot;">​</a></h2><p>On the <strong>Base SVG</strong> tab, pick a source:</p><ul><li><strong>Asset Library</strong>: built-in ship blueprints that ship with LCARdS (the easiest starting point)</li><li><strong>Browse HA Media</strong>: an SVG you&#39;ve uploaded to Home Assistant&#39;s media library</li><li><strong>Custom Path</strong>: a <code>/local/…</code> path or URL to your own SVG</li><li><strong>None</strong>: a blank canvas with no background image at all</li></ul><p>For your first MSD, pick an <strong>Asset Library</strong> ship.</p><div class="tip custom-block"><p class="custom-block-title">Free anchors</p><p>Built-in ships (and most SVGs) come with automatically-detected anchor points (<code>hull_center</code>, <code>extremity_bow</code>, <code>extremity_stern</code>, and similar) computed straight from the image&#39;s own silhouette. You can position your first controls against these without placing a single anchor by hand.</p></div><p><img src="'+l+'" alt="Screenshot: Base SVG tab, Asset Library source mode, a ship selected and visible on the canvas"></p><hr><h2 id="step-3-place-your-first-control" tabindex="-1">Step 3: Place Your First Control <a class="header-anchor" href="#step-3-place-your-first-control" aria-label="Permalink to &quot;Step 3: Place Your First Control&quot;">​</a></h2><p>Switch to the <strong>Controls</strong> tab and click <strong>Place on Canvas</strong> and then draw a box for the control on the canvas. When you release the mouse button, the <strong>Add Control</strong> dialog will open. Note: you can also do all placement and sizing in the <strong>Add Control</strong> dialog input fields.</p><p><img src="'+c+'" alt="Screenshot: Controls tab, empty state, &quot;Add Control&quot; button highlighted"></p><p>In the form that opens:</p><ol><li>Give your control an <strong>ID</strong>.</li><li>On the <strong>Card</strong> tab, pick the Home Assistant/LCARdS card you actually want displayed here - a button, a slider, a sensor tile, anything. You can configure it exactly like you would anywhere else in Lovelace.</li><li>Save the control.</li></ol><p><img src="'+d+'" alt="Screenshot: Add Control form, Card tab, a button card configured inside it"></p><p>Your control now appears positioned on the canvas, on top of the background.</p><hr><h2 id="step-4-connect-the-control-to-the-ship-with-a-line" tabindex="-1">Step 4: Connect The Control To The Ship With a Line <a class="header-anchor" href="#step-4-connect-the-control-to-the-ship-with-a-line" aria-label="Permalink to &quot;Step 4: Connect The Control To The Ship With a Line&quot;">​</a></h2><p>Switch to the <strong>Lines</strong> tab. There are two ways to draw a connection:</p><ul><li><strong>Add Line</strong> button: opens a form where you pick a source (<strong>Anchor</strong>) and destination (<strong>Attach To</strong>) from a dropdown of every control/anchor on the canvas, plus which side of each to depart/arrive from.</li><li><strong>Connect Line</strong> canvas tool (in the toolbar above the canvas): click it, then click on any connection point (orange dot) your control followed by any other control&#39;s connection point (orange dot) or Anchor (blue dot) directly on the canvas.</li></ul><p><img src="'+h+'" alt="Screenshot: canvas toolbar with &quot;Connect Line&quot; mode active, a line being drawn between two controls"></p><p>The <strong>Add Line</strong> dialog will open. Give your line an ID, or just accecpt the generated default. For now, leave all other options as is, and click <strong>Save</strong>. The line will find the currently best route automatically and be drawn on the canvas.</p><p><img src="'+g+'" alt="Screenshot: two controls connected by a routed line on the canvas"></p><hr><h2 id="step-5-save" tabindex="-1">Step 5: Save <a class="header-anchor" href="#step-5-save" aria-label="Permalink to &quot;Step 5: Save&quot;">​</a></h2><p>Skip <strong>Shapes</strong> and <strong>Routing</strong> for now; they&#39;re both optional. Shapes add decorative geometry (rooms, zones, conduit runs) once you want the canvas to feel more like a real schematic; Routing exposes global tuning knobs that are only worth touching once you&#39;ve noticed something you specifically want to change (curious how lines find their own path? see <a href="./routing-concepts.html">Routing Concepts</a>; full config reference: <a href="./routing.html">Routing &amp; Channels</a>).</p><p>Click <strong>Save</strong> in the Studio&#39;s footer, then save the card/dashboard as you normally would in Lovelace.</p><p><img src="'+u+'" alt="Screenshot: finished MSD card rendered on a dashboard, background + two controls + connecting line"></p><p>That&#39;s a complete minimal MSD: a background, a live control, and a line connecting control to the ship, all placed and drawn without writing any YAML.</p><hr><h2 id="where-to-go-next" tabindex="-1">Where to Go Next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to Go Next&quot;">​</a></h2><ul><li><a href="./control-overlay.html">Control Overlay</a>: every control placement/sizing option</li><li><a href="./line-overlay.html">Line Overlay</a>: routing modes, styling, markers, state-based color</li><li><a href="./routing-concepts.html">Routing Concepts</a>: the short version of how lines find their own path</li><li><a href="./routing.html">Routing &amp; Channels</a>: how automatic bundling works, and how to guide it</li><li><a href="./shape-overlay.html">Shape Overlay</a>: rooms, zones, and freeform geometry</li><li><a href="./">MSD Card</a>: full config reference, once you&#39;re ready to read/write the YAML directly</li></ul>',46)])])}const C=o(p,[["render",m]]);export{k as __pageData,C as default};
